let S={l:{},v:{},m:'Creative',g:'All',q:'',d:new Set(),sync:0,br:null,bv:'?',mods:{},h:null,s:null,p:null,to:null,pc:Math.min(20,Math.max(1,+gv('virag.plan.products',1)||1)),cc:Math.min(10,Math.max(1,+gv('virag.plan.creatives',2)||2)),am:gv('virag.plan.arrangement','separate')==='together'?'together':'separate',ty:Y[gv('virag.plan.type','auto')]?gv('virag.plan.type','auto'):'auto'};T.forEach(t=>{S.l[t]=new Map;S.v[t]='?'});
